package com.booksyde.controller;
import com.booksyde.dto.response.*; import com.booksyde.service.*; import java.util.*; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/marketplace") public class MarketplaceController { private final MarketplaceService service; public MarketplaceController(MarketplaceService s){service=s;} @GetMapping("/public/listings") public List<MarketplaceListingResponse> listings(){return service.publicListings();} @GetMapping("/orders") public List<MarketplaceOrderResponse> orders(@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt jwt){return service.buyerOrders(UUID.fromString(jwt.getSubject()));} @GetMapping("/seller/listings") public List<MarketplaceListingResponse> sellerListings(@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt jwt){return service.sellerListings(UUID.fromString(jwt.getSubject()));} @GetMapping("/seller/orders") public List<MarketplaceOrderResponse> sellerOrders(@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt jwt){return service.sellerOrders(UUID.fromString(jwt.getSubject()));}}
